validator:
function validate(input) {
  const [{ Files = [] }] = input;
  const names = new Set();
  for (const [name, content] of Files) {
    if (name === null) return 'Every file needs a file_name.';
    if (names.has(name)) return `file_name ${name} appears twice.`;
    names.add(name);
    if (content === null) return `File ${name} needs content.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const tokens = ['bull', 'bear', 'bull', 'bear', 'bullet', 'bears', 'bull.', 'bear,', 'abull', 'the', 'market', 'a', 'is', 'up', 'down', 'and'];
  const files = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const words = size === 'small' ? 6 : 30;
  const Files = [];
  for (let i = 1; i <= files; i++) {
    const parts = [];
    for (let k = 1 + Math.floor(rand() * words); k > 0; k--) parts.push(pick(tokens));
    Files.push([`file${i}.txt`, parts.join(' ')]);
  }
  return [{ Files }];
}
